SELECT 
FROM payment_transaction AS r
WHERE r.id = #{id}

SELECT 
FROM payment_transaction AS r
WHERE r.payment_key = #{paymentKey}

SELECT 
FROM payment_transaction AS r
WHERE r.order_seq = #{orderSeq}
  AND r.status = #{status}

SELECT 
FROM payment_transaction AS r
WHERE r.status = #{status}
  AND r.expired_at < #{now}

mapper.update:
UPDATE payment_transaction
SET expired_at = #{expiredAt}
WHERE id = #{id}

UPDATE payment_transaction
SET tid = #{tid},
    status = #{toStatus},
    fail_code = #{failCode},
    fail_message = #{failMessage}
WHERE id = #{id}
  AND status = #{fromStatus}
